use std::io::{self, Read};

fn input() -> Vec<String> {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    s.split_whitespace().map(|t| t.to_string()).collect()
}

/// Everything here is one chain each. No `for`, no `mut` accumulator.
fn evens_squared_sum(xs: &[i64]) -> i64 {
    xs.iter().filter(|x| *x % 2 == 0).map(|x| x * x).sum()
}

fn longest(words: &[String]) -> Option<&String> {
    words.iter().max_by_key(|w| w.len())
}

fn running(xs: &[i64]) -> Vec<i64> {
    xs.iter()
        .scan(0i64, |acc, x| {
            *acc += x;
            Some(*acc)
        })
        .collect()
}

fn main() {
    let t = input();
    if t.is_empty() {
        return;
    }
    let n: usize = t[0].parse().unwrap();
    let xs: Vec<i64> = t[1..1 + n].iter().map(|s| s.parse().unwrap()).collect();
    let words: Vec<String> = t[1 + n..].to_vec();

    println!("evensq {}", evens_squared_sum(&xs));
    match longest(&words) {
        Some(w) => println!("longest {}", w),
        None => println!("longest none"),
    }
    let r = running(&xs);
    let shown: Vec<String> = r.iter().map(|x| x.to_string()).collect();
    println!("running {}", shown.join(" "));
}
